1	<script setup lang="ts">
2	/**
3	 * Plain-text, keyboard-first conversation reader (UX-02). Opening is read-only —
4	 * never marks read.
5	 *
6	 * Visit-scoped message state (active message, expansion, details disclosure,
7	 * scroll anchor) lives inside this mounted reader instance, keyed by
8	 * account+conversation reference and message ID — never by array position. It
9	 * survives J/K round trips and same-reference background replacements within
10	 * the reader session and is released when the reader closes (component
11	 * unmount) or the account changes.
12	 *
13	 * Archive/read controls are shown only when the authoritative capability permits them, and
14	 * Gmail-supplied plain-text limitations are disclosed explicitly (`unsupportedReason`,
15	 * `contextComplete === false`) instead of silently dropping content.
16	 *
17	 * Safety: message content is rendered exclusively through text interpolation
18	 * ({{ }}). No v-html, no markdown/HTML processing, no remote assets anywhere in
19	 * this slice — hostile markup stays literal text. Reply preparation always
20	 * targets the explicitly displayed latest message, never the focused message.
21	 *
22	 * Message commands (N/P/O/Shift+O, details dismissal) are exposed as narrow
23	 * methods for App's single keyboard dispatcher — this component never adds its
24	 * own window listener.
25	 */
26	import { actionLabel } from '../lib/browsing-actions';
27	import { compactDateLabel, fullDateLabel, machineDateTime } from '../lib/browsing-dates';
28	import { messageSnippet } from '../lib/message-snippet';
29	import { bodyNeedsMonospace, splitMessageBody, type MessageBodyParts } from '../lib/message-body-format';
30	import { computed, nextTick, reactive, ref, useId, watch } from 'vue';
31	import HeaderGlyph from './HeaderGlyph.vue';
32	import MessageAttachments from './MessageAttachments.vue';
33	import { useAttachmentTransfer } from '../composables/useAttachmentTransfer';
34	import type { Address, Conversation, ConversationRef, DraftSource, MailClient, MailError, Message } from '../lib/ipc/client';
35	import type { AttachmentDescriptor } from '../lib/ipc/generated';
36	import type { DetailState } from '../composables/useMailbox';
37	
38	const props = defineProps<{
39	  conversation: Conversation | null;
40	  state: DetailState;
41	  error: MailError | null;
42	  commandInFlight: boolean;
43	  /** The conversation reference the shell currently wants displayed. */
44	  openRef: ConversationRef | null;
45	  /**
46	   * Target identity from the list's own row, shown while the target loads and
47	   * no previous conversation is held. Never message content.
48	   */
49	  loadingIdentity?: { subject: string; sender: string | null; at: string | null } | null;
50	  /** Gmail mode: archive/unarchive controls are hidden, not just disabled. */
51	  readOnly?: boolean;
52	  browsingOnly?: boolean;
53	  navigationUnavailable?: boolean;
54	  showReadControls?: boolean;
55	  /** Nonzero: shared controls dispatch to the SELECTION (§3.3), so the reader
56	   * offers explicit count-labelled desired-state controls instead of the open
57	   * conversation's single-state toggles (mixed selections included). */
58	  selectionCount?: number;
59	  selectionContext?: 'inbox' | 'saved' | 'done' | 'starred' | 'search';
60	  /** Header slots the quiet icon actions are teleported into; inline when null. */
61	  backHost?: HTMLElement | null;
62	  actionsHost?: HTMLElement | null;
63	  /** J/K availability; undefined hides the previous/next chevrons. */
64	  canMovePrev?: boolean;
65	  canMoveNext?: boolean;
66	  /** Inline attachment rows: without a client the reader shows none. */
67	  client?: MailClient;
68	  /** Browser preview: saves are modelled in memory and say so. */
69	  preview?: boolean;
70	}>();
71	
72	const emit = defineEmits<{
73	  close: [];
74	  /** Previous (-1) / next (+1) conversation, same path as K / J. */
75	  move: [delta: number];
76	  attachments: [origin: HTMLElement];
77	  archive: [];
78	  unarchive: [];
79	  setRead: [read: boolean];
80	  prepareReply: [source: DraftSource];
81	  /** Identity of the message that currently owns reader focus. */
82	  activeMessage: [messageId: string | null];
83	  /** Hover/focus participant context override; `null` restores the baseline. */
84	  contactOverride: [
85	    override:
86	      | { ref: ConversationRef; messageId: string; displayName: string | null; mailbox: string }
87	      | null,
88	  ];
89	}>();
90	
91	const container = ref<HTMLElement | null>(null);
92	const scrollerEl = ref<HTMLElement | null>(null);
93	const messageEls = new Map<string, HTMLElement>();
94	
95	/** Selected-scope toolbar mode: nonzero selection dispatches to the whole
96	 * selection with explicit count labels (§3.3); null keeps single behavior. */
97	const bulkScope = computed(() =>
98	  (props.selectionCount ?? 0) > 0
99	    ? { count: props.selectionCount!, context: props.selectionContext ?? 'inbox' }
100	    : null,
101	);
102	
103	type StarCoverage = NonNullable<Conversation['stars']>;
104	
105	/** Short visible star line; exact coverage moves to the title/description. */
106	function starSummary(stars: StarCoverage): string {
107	  if (stars.starredMessages > 0) return stars.knownMessages < stars.totalMessages ? 'Starred (partial)' : 'Starred';
108	  return stars.knownMessages === stars.totalMessages && stars.totalMessages > 0 ? 'Not starred' : 'Star state unknown';
109	}
110	
111	/** The line appears only with news: starred, incomplete coverage, or a pending
112	 * action (the effective value may then include unconfirmed intent). */
113	function starLine(conversation: NonNullable<typeof props.conversation>): { text: string; attention: boolean } | null {
114	  const stars = conversation.stars;
115	  if (!stars) return null;
116	  const complete = stars.totalMessages > 0 && stars.knownMessages === stars.totalMessages;
117	  const pending = Boolean(conversation.pendingOperationId);
118	  if (stars.starredMessages === 0 && complete && !pending) return null;
119	  return { text: starSummary(stars) + (pending ? ' (unconfirmed)' : ''), attention: !complete || pending };
120	}
121	
122	function starCoverageDetail(stars: StarCoverage): string {
123	  return `Effective star values known for ${stars.knownMessages} of ${stars.totalMessages} cached messages. Pending intent is not provider confirmation.`;
124	}
125	
126	const latestMessage = computed(() => props.conversation?.messages.at(-1) ?? null);
127	const replyBlockedReason = computed(() => {
128	  if (!props.conversation || !latestMessage.value) return 'No displayed latest message is available as a reply source.';
129	  if (props.conversation.retainedSnapshotAt) return 'Reply preparation is blocked for a retained snapshot; current message headers cannot be verified.';
130	  if (props.conversation.contextComplete === false) return 'Reply preparation is blocked because this cached conversation is incomplete.';
131	  if (props.conversation.replyContext && props.conversation.replyContext.sourceMessageId !== latestMessage.value.id) return 'Reply preparation is blocked because cached reply headers do not match the displayed latest message.';
132	  return null;
133	});
134	
135	const replySourceId = `reader-reply-source-${useId()}`;
136	const replyTargetLabel = computed(() => latestMessage.value
137	  ? `Reply targets the latest message from ${latestMessage.value.from.displayName ?? latestMessage.value.from.mailbox}`
138	  : '');
139	/** Conversation-specific actions exist only for a ready conversation. */
140	const actionable = computed(() => props.state === 'ready' && !!props.conversation);
141	/**
142	 * A previous conversation kept on screen while the J/K target loads. It is
143	 * display only: nothing in it is actionable as if it were the open thread.
144	 */
145	const held = computed(() => props.state === 'loading' && !!props.conversation && keyOfDisplayed() === null);
146	/** Header actions stay mounted (disabled, not removed) for as long as a conversation is open. */
147	const actionsShown = computed(() => props.openRef !== null || actionable.value);
148	const hasMetaRow = computed(() => {
149	  if (!(actionable.value || held.value)) return false;
150	  return !!(props.readOnly || props.showReadControls || bulkScope.value);
151	});
152	
153	/** The one rule for whether Prepare reply may run (button, glyph and the R key). */
154	function canPrepareReply(): boolean {
155	  return actionable.value && !props.browsingOnly && !!latestMessage.value && replyBlockedReason.value === null;
156	}
157	
158	/** Title for the reply controls: the action label with its key, plus the target. */
159	const replyTitle = computed(() => {
160	  if (!actionable.value) return actionLabel('reply');
161	  return replyBlockedReason.value ?? `${actionLabel('reply')}. ${replyTargetLabel.value}`;
162	});
163	
164	/** The standing guarantee behind the status line (hook per mode); Cached Trash has its own line and only names the mode. */
165	const readerStatus = computed(() => {
166	  // Cached Trash keeps its own line below; the status span only names the mode,
167	  // with no standing sentence or hook.
168	  if (props.browsingOnly) return { hook: undefined, word: 'Read-only', sentence: null };
169	  if (props.readOnly) {
170	    return {
171	      hook: 'reader-readonly',
172	      word: 'Read-only',
173	      sentence: 'Read-only Gmail view: messages are never marked as read. Opening this conversation does not change read state.',
174	    };
175	  }
176	  if (props.showReadControls) {
177	    return {
178	      hook: 'reader-no-auto-read',
179	      word: null,
180	      sentence: 'Opening this conversation does not change read state; use an explicit read control.',
181	    };
182	  }
183	  return null;
184	});
185	
186	function prepareReply(): void {
187	  // Reply always targets the explicitly displayed latest message; focusing an
188	  // older message never changes the reply contract.
189	  const conversation = props.conversation;
190	  const source = latestMessage.value;
191	  if (!conversation || !source || replyBlockedReason.value) return;
192	  emit('prepareReply', {
193	    kind: 'reply',
194	    conversation: { ...conversation.ref },
195	    sourceMessageId: source.id,
196	  });
197	}
198	
199	function describeError(error: MailError): string {
200	  switch (error.kind) {
201	    case 'not_found':
202	      return 'That conversation is no longer available.';
203	    case 'invalid_request':
204	      return `The request was rejected (invalid field: ${error.field}).`;
205	    case 'request_id_conflict':
206	      return 'The request conflicted with an earlier request ID.';
207	    case 'storage_unavailable':
208	      return 'Local storage is unavailable. The operation was not confirmed.';
209	    case 'profile_in_use':
210	      return 'Another window is using this profile.';
211	    case 'read_only':
212	      return 'Gmail is read-only; archiving is unavailable.';
213	    case 'not_configured':
214	      return 'Gmail is not configured on this device.';
215	    case 'auth_required':
216	      return 'Sign-in is required; cached conversations stay readable.';
217	    case 'auth_cancelled':
218	      return 'Sign-in was cancelled.';
219	    case 'auth_failed':
220	      return 'Sign-in failed. Cached conversations stay readable.';
221	    case 'secrets_unavailable':
222	      return 'Secure credential storage is unavailable.';
223	    case 'network_unavailable':
224	      return 'The network is unavailable; cached conversations stay readable.';
225	    case 'rate_limited':
226	      return 'The provider is rate limiting. Cached conversations stay readable.';
227	    case 'provider_unavailable':
228	      return 'The mail provider is temporarily unavailable.';
229	    case 'invalid_provider_response':
230	      return 'The provider returned an unexpected response.';
231	    case 'busy':
232	      return 'A sync is already in progress. Try again shortly.';
233	    case 'permission_required':
234	      return 'Google mailbox-action permission is not enabled.';
235	    case 'provider_rejected':
236	      return 'The provider rejected this action.';
237	    case 'outcome_unknown':
238	      return 'The remote result is uncertain. Review Activity before retrying.';
239	    default:
240	      return 'Could not load the conversation.';
241	  }
242	}
243	
244	// ---------------------------------------------------------------------------
245	// Visit-scoped message state, keyed by account+conversation
246	// ---------------------------------------------------------------------------
247	
248	/** Viewport-relative scroll anchor: a message top plus a scrollTop fallback. */
249	interface MessageAnchor { messageId: string; offsetTop: number; scrollTop: number }
250	
251	interface VisitState {
252	  activeMessageId: string | null;
253	  expandedIds: Set<string>;
254	  detailsOpenId: string | null;
255	  /** Messages whose trailing quoted text is shown. */
256	  quoteOpenIds: Set<string>;
257	  anchor: MessageAnchor | null;
258	  /** Message ordering this state was built against (for removed-ID resolution). */
259	  order: string[];
260	}
261	
262	const visits = new Map<string, VisitState>();
263	/** Reactive holder for the currently displayed visit. */
264	const visitRef = ref<VisitState | null>(null);
265	let lastDataKey: string | null = null;
266	/**
267	 * Foreground activation intent, tracked separately from `lastDataKey`: a
268	 * loading transition that removed reader-owned focus owes the next ready
269	 * snapshot a message-focus restoration, even when the user reverses back to
270	 * the same key as the last loaded one (which would otherwise be classified as
271	 * an unfocused same-reference background replacement).
272	 */
273	let pendingFocusRestore = false;
274	
275	function visitKey(ref: ConversationRef): string {
276	  return `${ref.accountId}:${ref.conversationId}`;
277	}
278	
279	function keyOfDisplayed(): string | null {
280	  const conversation = props.conversation;
281	  const open = props.openRef;
282	  if (!conversation || !open) return null;
283	  if (conversation.ref.accountId !== open.accountId || conversation.ref.conversationId !== open.conversationId) return null;
284	  return visitKey(conversation.ref);
285	}
286	
287	/**
288	 * Prune removed message IDs and resolve removed active/anchor IDs by the
289	 * surviving old neighbors (next surviving old neighbor, then previous), so a
290	 * background replacement can never leave a stale message target.
291	 */
292	function pruneVisit(visit: VisitState, nextIds: string[]): void {
293	  const present = new Set(nextIds);
294	  const resolve = (id: string | null): string | null => {
295	    if (id === null || present.has(id)) return id;
296	    const oldIndex = visit.order.indexOf(id);
297	    if (oldIndex >= 0) {
298	      for (let i = oldIndex + 1; i < visit.order.length; i += 1) {
299	        const candidate = visit.order[i]!;
300	        if (present.has(candidate)) return candidate;
301	      }
302	      for (let i = oldIndex - 1; i >= 0; i -= 1) {
303	        const candidate = visit.order[i]!;
304	        if (present.has(candidate)) return candidate;
305	      }
306	    }
307	    return null;
308	  };
309	  visit.activeMessageId = resolve(visit.activeMessageId);
310	  visit.detailsOpenId = visit.detailsOpenId !== null && present.has(visit.detailsOpenId) ? visit.detailsOpenId : null;
311	  if (visit.anchor && !present.has(visit.anchor.messageId)) {
312	    const resolved = resolve(visit.anchor.messageId);
313	    visit.anchor = resolved
314	      ? { ...visit.anchor, messageId: resolved }
315	      : { messageId: '', offsetTop: 0, scrollTop: visit.anchor.scrollTop };
316	  }
317	  visit.expandedIds = new Set([...visit.expandedIds].filter((id) => present.has(id)));
318	  visit.quoteOpenIds = new Set([...visit.quoteOpenIds].filter((id) => present.has(id)));
319	  visit.order = [...nextIds];
320	}
321	
322	function captureScrollAnchor(visit: VisitState): MessageAnchor | null {
323	  const scroller = scrollerEl.value;
324	  if (!scroller || visit.order.length === 0) return null;
325	  const scrollerTop = scroller.getBoundingClientRect().top;
326	  for (const id of visit.order) {
327	    const el = messageEls.get(id);
328	    if (!el) continue;
329	    const top = el.getBoundingClientRect().top;
330	    if (top >= scrollerTop - 1 || id === visit.order[visit.order.length - 1]) {
331	      return { messageId: id, offsetTop: top - scrollerTop, scrollTop: scroller.scrollTop };
332	    }
333	  }
334	  return null;
335	}
336	
337	function restoreScroll(visit: VisitState, scroller: HTMLElement): void {
338	  const anchor = visit.anchor;
339	  if (!anchor) return;
340	  const el = messageEls.get(anchor.messageId);
341	  if (!el || scroller.clientHeight === 0 || !anchor.messageId) {
342	    // Fallback: the anchored message no longer exists; restore the raw offset.
343	    scroller.scrollTop = anchor.scrollTop;
344	    return;
345	  }
346	  const relative = el.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
347	  scroller.scrollTop = scroller.scrollTop + (relative - anchor.offsetTop);
348	}
349	
350	function focusElement(el: HTMLElement | null | undefined, reveal: boolean): boolean {
351	  if (!el || !el.isConnected) return false;
352	  // Never move focus into an inert ancestor (e.g. a drawer covering the reader).
353	  if (el.closest('[inert]')) return false;
354	  el.focus({ preventScroll: true });
355	  if (reveal && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
356	  return document.activeElement === el;
357	}
358	
359	function focusMessageToggle(messageId: string, reveal: boolean): void {
360	  focusElement(messageEls.get(messageId)?.querySelector<HTMLElement>('.message-toggle'), reveal);
361	}
362	
363	type ComponentPublicInstance = import('vue').ComponentPublicInstance;
364	
365	function setMessageEl(el: Element | ComponentPublicInstance | null, messageId: string): void {
366	  if (el instanceof HTMLElement) messageEls.set(messageId, el);
367	  else messageEls.delete(messageId);
368	}
369	
370	let updateSeq = 0;
371	
372	/**
373	 * Loading teardown: if reader-owned focus was dropped to <body> because the
374	 * loading placeholder removed the focused message control, park it on the
375	 * persistent reader article. Never steals toolbar, rail, overlay, or other
376	 * unrelated focus — including a surface the user moved to while this delayed
377	 * work was in flight — respects inert ancestors, and is invalidated by any
378	 * newer update (a ready snapshot takes over via schedulePostUpdate).
379	 */
380	async function scheduleLoadingFocus(seq: number): Promise<void> {
381	  await nextTick();
382	  if (seq !== updateSeq) return;
383	  // Focus already lives on a surviving reader surface (e.g. the toolbar);
384	  // leave it exactly where it is.
385	  if (container.value?.contains(document.activeElement) ?? false) return;
386	  // Park only over focus that fell to <body> when the message control was
387	  // torn down: a still-focused rail/outside button keeps its focus.
388	  const active = document.activeElement;
389	  if (active !== null && active !== document.body) return;
390	  focusElement(container.value, false);
391	}
392	
393	/**
394	 * Post-update work for one conversation snapshot: restore the visit's scroll
395	 * position and, on a visit switch, focus the visit's active message toggle
396	 * (the article stays the empty/error fallback). The delayed focus is guarded
397	 * against a changed reference, a newer update, and inert ancestors.
398	 */
399	async function schedulePostUpdate(key: string, focusIntent: boolean, readerHadFocus: boolean, restoringAfterLoading: boolean, switched: boolean): Promise<void> {
400	  const seq = ++updateSeq;
401	  await nextTick();
402	  if (seq !== updateSeq || keyOfDisplayed() !== key) return;
403	  const visit = visits.get(key);
404	  const scroller = scrollerEl.value;
405	  if (visit && scroller) {
406	    // A returning visit restores its anchor; a first visit starts at the top
407	    // instead of inheriting the outgoing conversation's offset.
408	    if (visit.anchor) restoreScroll(visit, scroller);
409	    else if (switched) scroller.scrollTop = 0;
410	  }
411	  const messages = props.conversation?.messages ?? [];
412	  // A replacement that removed the focused message element must not drop
413	  // reader focus to <body>; resolve it to the visit's active message toggle.
414	  if (!focusIntent && readerHadFocus && !(container.value?.contains(document.activeElement) ?? false)) {
415	    if (messages.length === 0 || !visit?.activeMessageId) {
416	      focusElement(container.value, false);
417	      return;
418	    }
419	    // Scroll geometry was just restored; do not let focus-reveal shift it.
420	    focusMessageToggle(visit.activeMessageId, false);
421	    return;
422	  }
423	  if (!focusIntent) return;
424	  if (restoringAfterLoading) {
425	    // A delayed reversal must not yank focus from a surface the user moved to
426	    // while the loading placeholder was up: only our own parked article focus
427	    // (or focus that fell to <body>) may be promoted to a restoration target.
428	    // This ownership check must come BEFORE choosing the target so it also
429	    // protects the empty-visit article fallback, not just the message toggle.
430	    const active = document.activeElement;
431	    const inReader = active instanceof Node && (container.value?.contains(active) ?? false);
432	    if (inReader ? active !== container.value : active !== null && active !== document.body) return;
433	  }
434	  if (messages.length === 0 || !visit?.activeMessageId) {
435	    // Empty/error fallback: the reader article keeps focus instead of a
436	    // message control that does not exist.
437	    focusElement(container.value, false);
438	    return;
439	  }
440	  // A revisit with a saved anchor is positioned by restoreScroll; focusing
441	  // must not reveal-scroll and destroy the restored reading offset. A first
442	  // visit has no geometry yet, so reveal the focused header as needed.
443	  focusMessageToggle(visit.activeMessageId, visit.anchor === null);
444	}
445	
446	watch(
447	  () => props.conversation,
448	  (conversation) => {
449	    // Capture the outgoing visit's scroll geometry BEFORE any DOM teardown,
450	    // including the foreground null/loading transition: useMailbox clears the
451	    // conversation before the next detail arrives, and by the following
452	    // non-null update the outgoing message elements are already gone. This
453	    // watcher runs pre-flush, so the old elements are still live here. The
454	    // capture is a no-op once the elements are gone, so a loading/empty DOM
455	    // can never overwrite a saved anchor.
456	    const outgoing = lastDataKey !== null ? visits.get(lastDataKey) : null;
457	    if (outgoing && scrollerEl.value) {
458	      const captured = captureScrollAnchor(outgoing);
459	      if (captured) outgoing.anchor = captured;
460	    }
461	    const readerHadFocus = container.value?.contains(document.activeElement) ?? false;
462	    if (!conversation) {
463	      // Loading/error: visit state must not be erased. Only reader-owned
464	      // focus that is about to lose its message control is parked on the
465	      // persistent reader article (not <body>) and remembered for message
466	      // focus restoration on the next ready snapshot even when it resolves to
467	      // the last loaded key (immediate reversal). Focus that already lives
468	      // elsewhere (rail/overlay/outside) is never scheduled over.
469	      const seq = ++updateSeq;
470	      if (readerHadFocus) {
471	        pendingFocusRestore = true;
472	        void scheduleLoadingFocus(seq);
473	      }
474	      return;
475	    }
476	    const key = visitKey(conversation.ref);
477	    const previousKey = lastDataKey;
478	    const ids = conversation.messages.map((message) => message.id);
479	    let visit = visits.get(key);
480	    if (!visit) {
481	      const newest = ids[ids.length - 1] ?? null;
482	      // Reactive so state mutations (pruning resolution, command handlers)
483	      // publish through visitRef to templates and the active-ID watcher.
484	      visit = reactive<VisitState>({
485	        activeMessageId: newest,
486	        expandedIds: new Set(newest === null ? [] : [newest]),
487	        detailsOpenId: null,
488	        quoteOpenIds: new Set<string>(),
489	        anchor: null,
490	        order: [...ids],
491	      });
492	      visits.set(key, visit);
493	    } else {
494	      pruneVisit(visit, ids);
495	    }
496	    visitRef.value = visit;
497	    lastDataKey = key;
498	    // Foreground activation is tracked separately from the last loaded key:
499	    // a reversal back to the same key still owes a focus restoration.
500	    const restoringAfterLoading = pendingFocusRestore;
501	    pendingFocusRestore = false;
502	    // A same-reference replacement never changes focus; a visit switch or a
503	    // reversed loading transition does.
504	    void schedulePostUpdate(key, key !== previousKey || restoringAfterLoading, readerHadFocus, restoringAfterLoading, key !== previousKey);
505	  },
506	  { immediate: true, flush: 'pre' },
507	);
508	
509	/** Loading/error fallback: keep the reader article focused, never steal toolbar focus. */
510	watch(
511	  () => props.state,
512	  async (state) => {
513	    if (state !== 'error') return;
514	    const seq = ++updateSeq;
515	    await nextTick();
516	    if (seq !== updateSeq) return;
517	    const active = document.activeElement;
518	    if (active instanceof Node && container.value?.contains(active)) return;
519	    focusElement(container.value, false);
520	  },
521	);
522	
523	// Reader focus identity + participant context (App consumes these).
524	watch(
525	  () => visitRef.value?.activeMessageId ?? null,
526	  (activeId) => { emit('activeMessage', activeId); },
527	  { immediate: true },
528	);
529	
530	const hoverParticipant = ref<{ messageId: string; address: Address } | null>(null);
531	const focusParticipant = ref<{ messageId: string; address: Address } | null>(null);
532	// Keyboard focus overrides hover independently; both restore the baseline on exit.
533	const effectiveParticipant = computed(() => focusParticipant.value ?? hoverParticipant.value);
534	
535	watch(
536	  effectiveParticipant,
537	  (value) => {
538	    const open = props.openRef;
539	    if (!value || !open) {
540	      emit('contactOverride', null);
541	      return;
542	    }
543	    emit('contactOverride', {
544	      ref: { ...open },
545	      messageId: value.messageId,
546	      displayName: value.address.displayName,
547	      mailbox: value.address.mailbox,
548	    });
549	  },
550	);
