/* A visually hidden leading Today caption takes no box at all. */
.row-group.visually-hidden {
  min-height: 0;
  padding: 0;
}

/* Reader: a bounded flex surface with its own content scroller; the toolbar
   (and its Back affordance) stays persistent while the message stack scrolls. */
.reader-pane,
.reader {
  min-height: 0;
  min-width: 0;
}

.reader-pane {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0.75rem;
}

.reader {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.reader:focus {
  outline: none;
}

/* Quiet icon actions teleported into the app header: the hosts take no box of
   their own so the glyphs sit on the header's 32px pitch. Standalone (no
   host) they flow inline. */
.reader-back-host,
.reader-actions-host {
  display: contents;
}

.reader-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
}

/* Back arrow leads the context title; its glyph sits on the 50px inset. */
.header-tabs > .reader-back-host > .reader-back {
  align-self: center;
  margin-left: -8px;
  margin-right: -10px;
}

.header-tabs:has(> .reader-back-host > .reader-back) {
  align-items: center;
}

/* Honest-state text controls under the subject: one quiet line, only when present. */
.reader-meta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 12px;
  color: var(--text-secondary);
}

.reader-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

/* Headline at the strong weight: the subject leads the reader without a third size. */
.reader-subject {
  font-size: var(--type-headline);
  font-weight: var(--weight-strong);
  line-height: var(--leading-headline);
  overflow-wrap: anywhere;
}

/* Loading identity: the list row's sender and date under the subject, then one
   quiet line. No motion; same type scale as the loaded reader. */
.reader-loading-identity {
  display: flex;
  gap: 12px;
  margin: 0.2rem 0;
  color: var(--text-secondary);
}

.reader-loading-quiet {
  color: var(--text-secondary);
}

/* Static placeholder bars in the Rule colour: the subject line, then rows at the
   collapsed message height (2em). No shimmer: nothing moves while loading. */
.reader-skeleton {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.reader-skeleton-subject,
.reader-skeleton-row {
  display: block;
  background: var(--rule);
  border-radius: 4px;
  opacity: 0.6;
}

.reader-skeleton-subject {
  height: var(--type-headline);
  width: 40%;
}

.reader-skeleton-row {
  height: 1.4em;
  width: 100%;
}

.reader-context-note {
  max-width: 80ch;
  margin: 0.2rem 0;
  color: var(--text-secondary);
  font-size: var(--type-body);
}

/* Partial, unknown and unconfirmed star state read as Amber Notice. */
.reader-context-note[data-attention] {
  color: var(--warning);
}

.reader-pending {
  margin: 0.2rem 0;
  color: var(--warning);
  font-size: var(--type-body);
}

/* The standing read-state guarantee: one muted status line in the meta row.
   The sentence itself is its title and visually hidden text. */
.reader-status {
  display: inline-flex;
  align-items: baseline;
  gap: 0.35em;
}

.reader-status-word::after {
  content: ' ·';
