:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

button:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: 1px;
}

/* Fields (DESIGN.md "Inputs / Fields"): Lifted Charcoal, 1px Seam, 4px radius;
   on keyboard focus the border shifts to Dusk Lavender (no glow), doubled by a
   1px inner outline so the ring reads at 12px. */
:where(input:not([type='checkbox'], [type='radio']), textarea, select) {
  font: inherit;
  background: var(--surface-raised);
  color: var(--text-primary);
  border: 1px solid var(--divider);
  border-radius: 4px;
}

:where(input:not([type='checkbox'], [type='radio']), textarea, select):focus-visible {
  border-color: var(--focus-accent);
  outline: 1px solid var(--focus-accent);
  outline-offset: -2px;
}

:where(input[type='checkbox'], input[type='radio']):focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: 1px;
}

:where(input, textarea)::placeholder {
  color: var(--text-tertiary);
  opacity: 1;
}

